<script setup lang="ts">
import {can} from './session'
import {ref,reactive,computed,onMounted,onBeforeUnmount} from 'vue'
import {api,session} from './session'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useTableWidths} from './tableWidths'
import CustomsFields from './CustomsFields.vue'
import {defaults,sharedFields,withDefaults} from './customsData'
const props=defineProps<{productId?:number}>(),emit=defineEmits<{saved:[data:{id:number,name:string}],close:[]}>(),tableWidths=useTableWidths('ProductEditor'),admin=computed(()=>can('products.products','operate')),options=reactive({suppliers:[] as string[]})
const drawer=ref(true),saving=ref(false),editingId=ref<number|null>(null),source=ref<any>({}),history=ref<any[]>([]),archived=ref(false)
const imagePreview=ref(''),imageBusy=ref(false)
const profileOptions=ref<any[]>([]),profileLoading=ref(false)
let profileSeq=0,rendered:any={},renderedCommon:any={},profileApplied=false
async function searchProfiles(q=''){const n=++profileSeq;profileLoading.value=true;try{const d=await api('/customs/profiles?'+new URLSearchParams({q,page_size:'100'}));if(n===profileSeq)profileOptions.value=d.rows}catch(e){ElMessage.error((e as Error).message)}finally{if(n===profileSeq)profileLoading.value=false}}
async function applyProfile(id:number|null){if(!id)return;try{const p=await api('/customs/profiles/'+id);if(form.customs_profile_id!==id)return;for(const k of ['declaration','clearance'] as const){form[k]=JSON.parse(JSON.stringify(p[k]));for(const field of ['unit_price','tax_rate'])form[k][field]=form[k][field]==null?null:Number(form[k][field])}for(const k of Object.keys(sharedFields))common[k]=p.declaration[k]||p.clearance[k]||'';profileApplied=true;sharedConflict.value=false}catch(e){ElMessage.error((e as Error).message)}}
const empty=()=>({customs_profile_id:null as number|null,image_path:null as string|null,freight_uk_cny:null as number|null,freight_eu_cny:null as number|null,code:'',name:'',cost_cny:null as number|null,primary_supplier:'',suppliers:[] as string[],specification:'',package_length_cm:null as number|null,package_width_cm:null as number|null,package_height_cm:null as number|null,gross_weight_g:null as number|null,category:'',unit:'',notes:'',purchase_url:'',declaration:defaults() as Record<string,any>,clearance:defaults() as Record<string,any>,revision:null as number|null})
async function uploadImage(event:Event){
 const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return
 if(file.size>5*1024*1024){ElMessage.warning('图片不能超过5MB');input.value='';return}
 imageBusy.value=true
 try{const response=await fetch('/api/products/images',{method:'POST',headers:{'X-ERP-Client':'web','Content-Type':file.type||'application/octet-stream'},body:file});const d=await response.json();if(!response.ok)throw new Error(d.detail||'图片上传失败');form.image_path=d.image_path;imagePreview.value=d.image_path;ElMessage.success('图片已上传，保存商品后生效')}catch(e){ElMessage.error((e as Error).message)}finally{imageBusy.value=false;input.value=''}
}
const form=reactive(empty()),common=reactive<Record<string,any>>({}),sharedConflict=ref(false);let baseline=''
const state=()=>JSON.stringify({form,common})
const freightUK=computed({get:()=>form.freight_uk_cny??(form.gross_weight_g==null?null:Number((form.gross_weight_g*15/1000).toFixed(4))),set:(v:number|null)=>{form.freight_uk_cny=v}})
const freightEU=computed({get:()=>form.freight_eu_cny??(form.gross_weight_g==null?null:Number((form.gross_weight_g*20/1000).toFixed(4))),set:(v:number|null)=>{form.freight_eu_cny=v}})
async function edit(row?:any){
 try{const p=row?await api('/products/'+row.id):null;editingId.value=p?.id??null;Object.assign(form,empty());if(p){for(const key of Object.keys(form))if(key in p)(form as any)[key]=p[key];for(const k of ['cost_cny','freight_uk_cny','freight_eu_cny','package_length_cm','package_width_cm','package_height_cm','gross_weight_g'])(form as any)[k]=p[k]==null?null:Number(p[k])};for(const kind of ['declaration','clearance'] as const){form[kind]=withDefaults(form[kind]);for(const key of ['unit_price','tax_rate'])form[kind][key]=form[kind][key]==null?null:Number(form[kind][key])};imagePreview.value=p?.image_url||'';source.value=p?.source||{};history.value=p?.history||[];archived.value=!!p?.archived;sharedConflict.value=Object.keys(sharedFields).some(k=>p?.declaration?.[k]&&p?.clearance?.[k]&&p.declaration[k]!==p.clearance[k]);for(const k of Object.keys(sharedFields))common[k]=p?.declaration?.[k]||p?.clearance?.[k]||form.declaration[k]||'';rendered=JSON.parse(JSON.stringify({declaration:form.declaration,clearance:form.clearance}));renderedCommon={...common};profileApplied=false;if(form.customs_profile_id){try{const selected=await api('/customs/profiles/'+form.customs_profile_id);profileOptions.value=[selected,...profileOptions.value.filter(x=>x.id!==selected.id)]}catch{}}baseline=state();drawer.value=true}catch(e){ElMessage.error((e as Error).message)}
}
async function canLeave(){if(!drawer.value||baseline===state())return true;try{await ElMessageBox.confirm('尚有未保存的商品信息，确定放弃修改？','离开编辑',{type:'warning',confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function closeDrawer(done:()=>void){if(await canLeave())done()}
defineExpose({canLeave})
async function save(){
 if(imageBusy.value||saving.value)return
 if(!form.code.trim()||!form.name.trim()){ElMessage.warning('请填写标品编码和品名');return}
 saving.value=true
 try{const customs:any={};for(const kind of ['declaration','clearance'] as const){const value={...form[kind]};for(const k of Object.keys(sharedFields))if(!editingId.value||profileApplied||common[k]!==renderedCommon[k])value[k]=common[k];const patch:any={};for(const [k,v] of Object.entries(value))if(!editingId.value||profileApplied||JSON.stringify(v)!==JSON.stringify(rendered[kind]?.[k]))patch[k]=v;if(Object.keys(patch).length)customs[kind]=patch}form.suppliers=form.primary_supplier?[form.primary_supplier]:[];const d=await api('/products'+(editingId.value?'/'+editingId.value:''),{...Object.fromEntries(Object.entries(form).filter(([k])=>!['declaration','clearance'].includes(k))),...customs});editingId.value=editingId.value||d.id;baseline=state();emit('saved',{id:editingId.value!,name:form.name});ElMessage.success('产品已保存')}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}
}
const cost=(n:any)=>n==null?'未维护':'¥'+Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4})
const time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—'
const actionNames:Record<string,string>={product_packaging_import:'导入包装规格与重量',product_merge:'合并统一编码商品',product_normalize:'统一 GM 编码',product_import:'从领星导入',product_create:'新增',product_update:'修改',product_archive:'移入回收站',product_restore:'恢复'}

onMounted(async()=>{try{options.suppliers=(await api('/products/options')).suppliers;await edit(props.productId?{id:props.productId}:undefined)}catch(e){ElMessage.error((e as Error).message)}})
function unload(e:BeforeUnloadEvent){if(baseline!==state()){e.preventDefault();e.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',unload));onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<template><section class="product-editor"><div class="editor-toolbar"><h2>{{editingId?'编辑产品':'新增产品'}}</h2><div><el-button @click="emit('close')">关闭</el-button><el-button v-if="admin&&!archived" type="primary" :loading="saving" @click="save">保存产品</el-button></div></div>  <el-alert v-if="archived" title="此标品在回收站中，恢复后可编辑。" type="info" :closable="false"/>
  <h3>基本信息与采购</h3><el-form label-position="top" :disabled="!admin||archived||saving" class="product-form editor-grid">
   <el-form-item label="标品编码 *"><el-input v-model="form.code" placeholder="内部唯一编码，例如 DEMO-Product-Black-6P" maxlength="255"/></el-form-item>
   <el-form-item label="品名 *"><el-input v-model="form.name" placeholder="便于仓库和采购识别的中文品名" maxlength="500"/></el-form-item>
   <el-form-item label="商品图片" class="product-photo"><div class="image-editor"><el-image v-if="imagePreview" :src="imagePreview" fit="contain" class="catalog-image large"/><label class="upload-image">上传图片<input type="file" aria-label="上传商品图片" accept="image/png,image/jpeg,image/webp" :disabled="imageBusy||!admin||archived" @change="uploadImage"/></label><el-button v-if="form.image_path" link @click="form.image_path=null;imagePreview=''">恢复关联 SKU 主图</el-button><small>默认使用关联 SKU 的一张主图；可上传 JPG / PNG / WebP，最大5MB。</small></div></el-form-item>
   <div class="pack-freight"><section><h4>产品规格</h4><el-form-item label="规格说明"><el-input v-model="form.specification" maxlength="2000"/></el-form-item><el-form-item v-for="(label,key) in {package_length_cm:'包装长 (cm)',package_width_cm:'包装宽 (cm)',package_height_cm:'包装高 (cm)',gross_weight_g:'单品毛重 (g)'}" :key="key" :label="label"><el-input-number v-model="form[key]" :aria-label="label" :min="0.0001" :max="9999999999" :precision="4" controls-position="right"/></el-form-item></section><section><h4>头程运费</h4><el-form-item label="英国头程运费（CNY/件）"><el-input-number v-model="freightUK" aria-label="英国头程运费" :min="0" :precision="4" controls-position="right"/><small>{{form.freight_uk_cny==null?'按重量自动计算 · 15元/kg':'使用手动金额'}}</small><el-button v-if="form.freight_uk_cny!=null" link @click="form.freight_uk_cny=null">恢复自动</el-button></el-form-item><el-form-item label="其他欧洲头程运费（CNY/件）"><el-input-number v-model="freightEU" aria-label="其他欧洲头程运费" :min="0" :precision="4" controls-position="right"/><small>{{form.freight_eu_cny==null?'按重量自动计算 · 20元/kg':'使用手动金额'}}</small><el-button v-if="form.freight_eu_cny!=null" link @click="form.freight_eu_cny=null">恢复自动</el-button></el-form-item><p class="field-hint">输入克重后自动计算每件运费；也可手动调整金额。</p></section></div>
   <el-form-item label="参考采购成本（CNY / 一个标品单位）"><el-input-number v-model="form.cost_cny" :min="0" :max="99999999999999" :precision="4" :step="0.1" controls-position="right"/><span class="field-hint">空白表示未维护，0 表示原记录为零。</span></el-form-item>
   <el-form-item label="供应商"><el-select v-model="form.primary_supplier" clearable filterable allow-create default-first-option placeholder="选择或输入供应商"><el-option v-for="s in [...new Set([...options.suppliers,...form.suppliers])]" :key="s" :label="s" :value="s"/></el-select></el-form-item>
   <el-form-item label="采购链接（选填）"><el-input v-model="form.purchase_url" placeholder="https://…" maxlength="2000"/></el-form-item>
   <el-form-item label="备注" class="product-notes"><el-input v-model="form.notes" type="textarea" :rows="14" maxlength="5000"/></el-form-item>
   <el-form-item label="清关&报关信息" class="editor-wide"><div class="profile-selector"><el-select v-model="form.customs_profile_id" clearable filterable remote :remote-method="searchProfiles" :loading="profileLoading" aria-label="清关报关资料选择" placeholder="输入商品名称查询资料" @visible-change="(v:boolean)=>v&&searchProfiles()" @change="applyProfile"><el-option v-for="p in profileOptions" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button v-if="form.customs_profile_id" @click="applyProfile(form.customs_profile_id)">重新带入</el-button></div><small>选中后带入下方字段，保存产品后生效。清空关联会保留当前内容；旧产品未关联时保持原样。</small></el-form-item>
  </el-form><section class="customs-section"><h3>报关 / 清关共用基础信息</h3><el-alert v-if="sharedConflict" title="原报关与清关有不同的基础资料，当前优先展示报关值；未修改时保留原数据，修改共用字段后才会统一两处内容。" type="warning" :closable="false"/><el-form label-position="top" :disabled="!admin||archived||saving"><CustomsFields :model-value="common" kind="declaration" mode="shared"/></el-form></section><section class="customs-section"><h3>报关信息</h3><el-form label-position="top" :disabled="!admin||archived||saving"><CustomsFields :model-value="form.declaration" kind="declaration" mode="specific"/></el-form></section><section class="customs-section"><h3>清关信息</h3><el-form label-position="top" :disabled="!admin||archived||saving"><CustomsFields :model-value="form.clearance" kind="clearance" mode="specific"/></el-form></section>
  <div v-if="source.packaging_import" class="source-box"><b>包装规格与重量原始记录</b><p>{{source.packaging_import.file}} · {{source.packaging_import.imported_at?time(source.packaging_import.imported_at):''}}</p><p v-if="source.packaging_import.conflicts?.length">旧记录存在差异，冲突值未自动选定；核对后可在上方填写。原始记录保留在此。</p><p>原表中为0或空白的尺寸、重量按未维护处理。</p><template v-if="true"><TableReset table-key="ProductPanel/table-2"/><el-table border data-width-key="ProductPanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="source.packaging_import.records" size="small"><el-table-column :column-key="'code'" :width="tableWidths.width('table-2', 'code', undefined)" prop="code" label="原编码" min-width="190"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-2', 'column-2', undefined)" label="长 × 宽 × 高 (cm)" align="center" min-width="145"><template #default="{row}">{{[row.package_length_cm,row.package_width_cm,row.package_height_cm].map(v=>v==null?'—':Number(v)).join(' × ')}}</template></el-table-column><el-table-column :column-key="'column-3'" label="毛重 (g)" :width="tableWidths.width('table-2', 'column-3', '90')" align="center"><template #default="{row}">{{row.gross_weight_g==null?'—':Number(row.gross_weight_g)}}</template></el-table-column></el-table></template></div>
  <div v-if="source.normalization" class="source-box"><b>编码整理记录</b><p>原编码：{{source.normalization.aliases?.join(' / ')}}</p><p v-for="note in source.normalization.review_notes" :key="note">{{note}}</p><p v-if="source.normalization.merged_into">已合并到标品 ID {{source.normalization.merged_into}}</p></div><div v-if="source.file" class="source-box"><b>领星原始记录</b><p>{{source.file}} · {{source.sheet}} 第 {{source.row}} 行</p><p>原创建人：{{source.creator||'—'}} · 原创建时间：{{source.created||'—'}}</p></div>
  <el-collapse v-if="history.length"><el-collapse-item title="最近操作记录" name="history"><div v-for="(h,i) in history" :key="i" class="audit-row">{{actionNames[h.action]||h.action}} · {{h.actor}}<small>{{time(h.at)}}</small><details v-if="h.detail.before"><summary>查看修改前后</summary><pre>{{JSON.stringify(h.detail,null,2)}}</pre></details></div></el-collapse-item></el-collapse>
<div class="editor-footer"><el-button @click="emit('close')">关闭</el-button><el-button v-if="admin&&!archived" type="primary" :loading="saving" @click="save">保存产品</el-button></div></section></template>
<style scoped>.product-editor{background:white;padding:22px 28px;max-width:1280px;margin:20px auto;border:1px solid #dce6e1;border-radius:8px;box-sizing:border-box} .pack-freight{grid-column:1/3;grid-row:2;display:grid;grid-template-columns:1fr 1fr;gap:32px;max-width:850px;margin-bottom:20px}.pack-freight section{padding:16px 20px;background:#f7faf8;border:1px solid #e5ece8;border-radius:6px}.pack-freight .el-form-item{margin-bottom:14px}.pack-freight small{display:block;width:100%}.pack-freight h4{margin:0 0 16px} .editor-toolbar{padding-bottom:18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e5ece8;margin-bottom:24px}.editor-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 22px}.editor-grid .el-select,.editor-grid .el-input-number{width:100%}.editor-wide{grid-column:1/-1}.form-two{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.customs-section{border-top:1px solid #e5ece8;padding-top:16px;margin-top:18px}.editor-footer{display:flex;justify-content:flex-end;position:sticky;bottom:0;background:white;padding:14px 0;border-top:1px solid #e5ece8;z-index:2}.catalog-image{width:85px;height:85px}.image-editor{display:flex;gap:10px;align-items:center;flex-direction:column;width:100%}.product-photo{grid-column:3;grid-row:1}.product-notes{grid-column:3;grid-row:2}.catalog-image.large{width:180px;height:180px}.upload-image{position:relative;padding:8px 18px;border:1px solid #b8d2c7;border-radius:5px;color:#227660;cursor:pointer}.upload-image input{position:absolute;inset:0;width:100%;opacity:0;cursor:pointer}.profile-selector{display:flex;gap:12px;width:min(740px,100%)}.profile-selector .el-select{flex:1}.editor-wide small{display:block;width:100%}.field-hint,small{font-size:12px;color:#87978e}.source-box{margin:16px 0;padding:12px;background:#f7faf8}.audit-row{padding:10px}.audit-row small{margin-left:14px}@media(max-width:1000px){.product-photo,.product-notes,.pack-freight{grid-row:auto;grid-column:auto}.pack-freight{grid-column:1/-1}.editor-grid,.form-two{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
